effect.shader:
float hash21(vec2 p) {
    p = fract(p * vec2(127.1, 311.7));
    p += dot(p, p + 34.23);
    return fract(p.x * p.y);
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);
    vec2 uv = acScreenNorm * vec2(acAspect, 1.0);

    vec2 p1 = point1 * vec2(acAspect, 1.0);
    vec2 p2 = point2 * vec2(acAspect, 1.0);
    vec2 p3 = point3 * vec2(acAspect, 1.0);
    vec2 p4 = point4 * vec2(acAspect, 1.0);

    // A faixa 1..8 é onde a transição continua macia (não vira um recorte
    // duro cedo demais), mas ainda dá pra sentir cada ponto dominando perto
    // de si quando `sharpness` sobe.
    float power = mix(1.0, 8.0, sharpness);

    float w1 = 1.0 / pow(max(distance(uv, p1), 0.0001), power);
    float w2 = 1.0 / pow(max(distance(uv, p2), 0.0001), power);
    float w3 = 1.0 / pow(max(distance(uv, p3), 0.0001), power);
    float w4 = 1.0 / pow(max(distance(uv, p4), 0.0001), power);
    float total = w1 + w2 + w3 + w4;

    vec3 mixed = (color1.rgb * w1 + color2.rgb * w2 + color3.rgb * w3 + color4.rgb * w4) / total;

    // Mesmo espalhamento de `gradient-ramp.xml`: um ruído minúsculo antes de
    // arredondar quebra o banding de 8 bits num degradê suave.
    if (scatter > 0.0) {
        mixed += (hash21(acScreenNorm * acResolution) - 0.5) * scatter;
    }
    mixed = clamp(mixed, 0.0, 1.0);

    fragColor = vec4(mixed, original.a);
}
